package rss // import "miniflux.app/v2/internal/reader/rss"

import (
	"bytes"
	"testing"
)

func TestAcceptanceProtocolRelativeEntryLinkUsesFeedScheme(t *testing.T) {
	scenarios := []struct {
		name     string
		feedURL  string
		siteURL  string
		itemLink string
		expected string
	}{
		{
			name:     "plain http feed keeps http",
			feedURL:  "http://intranet.example/feed.xml",
			siteURL:  "http://intranet.example/",
			itemLink: "//intranet.example/post/1",
			expected: "http://intranet.example/post/1",
		},
		{
			name:     "https feed keeps https",
			feedURL:  "https://blog.example/feed.xml",
			siteURL:  "https://blog.example/",
			itemLink: "//blog.example/post/2",
			expected: "https://blog.example/post/2",
		},
	}

	for _, scenario := range scenarios {
		t.Run(scenario.name, func(t *testing.T) {
			data := `<?xml version="1.0" encoding="utf-8"?>
<rss version="2.0">
<channel>
	<title>Example</title>
	<link>` + scenario.siteURL + `</link>
	<item>
		<title>Post</title>
		<link>` + scenario.itemLink + `</link>
	</item>
</channel>
</rss>`

			feed, err := Parse(scenario.feedURL, bytes.NewReader([]byte(data)))
			if err != nil {
				t.Fatal(err)
			}

			if len(feed.Entries) != 1 {
				t.Fatalf("expected 1 entry, got %d", len(feed.Entries))
			}

			if feed.Entries[0].URL != scenario.expected {
				t.Errorf("entry URL = %q, want %q", feed.Entries[0].URL, scenario.expected)
			}
		})
	}
}

