package json // import "miniflux.app/v2/internal/reader/json"

import (
	"bytes"
	"testing"
	"time"
)

func TestAcceptanceJSONFeedDateWithTwoDigitYear(t *testing.T) {
	data := `{
		"version": "https://jsonfeed.org/version/1.1",
		"title": "Two digit years",
		"home_page_url": "https://example.org/",
		"feed_url": "https://example.org/feed.json",
		"items": [
			{
				"id": "1",
				"url": "https://example.org/1",
				"content_text": "First",
				"date_published": "24-03-05T10:00:00+00:00"
			},
			{
				"id": "2",
				"url": "https://example.org/2",
				"content_text": "Second",
				"date_published": "23-11-30T22:15:00+02:00"
			}
		]
	}`

	feed, err := Parse("https://example.org/feed.json", bytes.NewBufferString(data))
	if err != nil {
		t.Fatal(err)
	}

	if len(feed.Entries) != 2 {
		t.Fatalf("expected 2 entries, got %d", len(feed.Entries))
	}

	expected := []time.Time{
		time.Date(2024, time.March, 5, 10, 0, 0, 0, time.UTC),
		time.Date(2023, time.November, 30, 20, 15, 0, 0, time.UTC),
	}

	for i, want := range expected {
		if got := feed.Entries[i].Date; !got.Equal(want) {
			t.Errorf("entry %d date = %v, want %v", i, got, want)
		}
	}
}

