package cli // import "miniflux.app/v2/internal/cli"

import (
	"bytes"
	"context"
	"log/slog"
	"os"
	"testing"

	"miniflux.app/v2/internal/config"
)

func TestAcceptanceLogLevelIsCaseInsensitive(t *testing.T) {
	previousLogger := slog.Default()
	defer slog.SetDefault(previousLogger)

	scenarios := []struct {
		value        string
		enabledLevel slog.Level
		belowLevel   slog.Level
		checkBelow   bool
	}{
		{value: "DEBUG", enabledLevel: slog.LevelDebug},
		{value: "Warning", enabledLevel: slog.LevelWarn, belowLevel: slog.LevelInfo, checkBelow: true},
		{value: "ERROR", enabledLevel: slog.LevelError, belowLevel: slog.LevelWarn, checkBelow: true},
	}

	for _, scenario := range scenarios {
		t.Run(scenario.value, func(t *testing.T) {
			os.Clearenv()
			os.Setenv("LOG_LEVEL", scenario.value)

			opts, err := config.NewConfigParser().ParseEnvironmentVariables()
			if err != nil {
				t.Fatalf("LOG_LEVEL=%s should be accepted, got error: %v", scenario.value, err)
			}

			var buf bytes.Buffer
			if err := InitializeDefaultLogger(opts.LogLevel(), &buf, opts.LogFormat(), opts.LogDateTime()); err != nil {
				t.Fatalf("unable to initialize logger: %v", err)
			}

			ctx := context.Background()
			if !slog.Default().Enabled(ctx, scenario.enabledLevel) {
				t.Errorf("LOG_LEVEL=%s should enable %v logs", scenario.value, scenario.enabledLevel)
			}
			if scenario.checkBelow && slog.Default().Enabled(ctx, scenario.belowLevel) {
				t.Errorf("LOG_LEVEL=%s should not enable %v logs", scenario.value, scenario.belowLevel)
			}
		})
	}
}

