package rewrite // import "miniflux.app/v2/internal/reader/rewrite"

import (
	"regexp"
	"strings"
	"testing"

	"miniflux.app/v2/internal/model"
)

func TestAcceptanceInvidiousPlayerIs640x360(t *testing.T) {
	entry := &model.Entry{
		URL:     "https://yewtu.be/watch?v=dQw4w9WgXcQ&t=30s",
		Title:   "A title",
		Content: "Video description",
	}

	ApplyContentRewriteRules(entry, "add_invidious_video")

	iframeTag := regexp.MustCompile(`<iframe[^>]*>`).FindString(entry.Content)
	if iframeTag == "" {
		t.Fatalf("expected an embedded player, got %q", entry.Content)
	}

	for _, expectedAttr := range []string{
		`src="https://yewtu.be/embed/dQw4w9WgXcQ?t=30s"`,
		`width="640"`,
		`height="360"`,
	} {
		if !strings.Contains(iframeTag, expectedAttr) {
			t.Errorf("expected player tag %q to contain %s", iframeTag, expectedAttr)
		}
	}

	if !strings.Contains(entry.Content, "Video description") {
		t.Errorf("original content should be kept, got %q", entry.Content)
	}
}

