package api // import "miniflux.app/v2/internal/api"

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestAcceptanceBulkEntryStatusUpdateRejectsRemoved(t *testing.T) {
	// No storage is configured: a rejected request must be answered before any database access.
	h := &handler{}

	body := strings.NewReader(`{"entry_ids": [1, 2, 3], "status": "removed"}`)
	r := httptest.NewRequest(http.MethodPut, "/v1/entries", body)
	r.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()

	func() {
		defer func() {
			if recovered := recover(); recovered != nil {
				t.Fatalf("status \"removed\" was not rejected before reaching storage: %v", recovered)
			}
		}()
		h.setEntryStatus(w, r)
	}()

	if w.Code != http.StatusBadRequest {
		t.Fatalf("expected HTTP %d, got %d (body: %s)", http.StatusBadRequest, w.Code, w.Body.String())
	}
}

