package readingtime

import (
	"strings"
	"testing"
)

func TestAcceptanceWordsSeparatedOnlyByTagsAreCounted(t *testing.T) {
	scenarios := map[string]string{
		"paragraphs":  "<p>word</p>",
		"line breaks": "word<br>",
		"list items":  "<li>word</li>",
	}

	for name, fragment := range scenarios {
		t.Run(name, func(t *testing.T) {
			// 400 words with no whitespace between them, only markup.
			content := "<div>" + strings.Repeat(fragment, 400) + "</div>"

			// 400 words at 200 words per minute is 2 minutes.
			if got := EstimateReadingTime(content, 200, 500); got != 2 {
				t.Errorf("EstimateReadingTime() = %d minutes, want 2", got)
			}
		})
	}
}
